// confirm / prompt / alert 不是畫面上的文字,另外包一層: 依所選語言翻譯後再顯示
(function () {
  ["alert", "confirm", "prompt"].forEach(k => {
    const orig = window[k]; if (typeof orig !== "function") return;
    window[k] = function (msg, ...rest) {
      try { const T = window.SGS_I18N && window.SGS_I18N.tr; if (T && typeof msg === "string") msg = msg.split("\n").map(l => T(l)).join("\n"); } catch (e) {}
      return orig.call(window, msg, ...rest);
    };
  });
})();
